begin;

select plan(36);

select ok(not has_function_privilege('authenticated', 'public.begin_question(uuid,text,uuid)', 'execute'), 'Guests cannot call the Question persistence function directly');
select ok(not has_function_privilege('authenticated', 'public.retrieve_passages(uuid,extensions.vector,integer,double precision)', 'execute'), 'Guests cannot call Retrieval directly');
select ok(not has_function_privilege('authenticated', 'public.set_question_evidence(uuid,uuid[])', 'execute'), 'Guests cannot nominate their own evidence set');
select ok(not has_function_privilege('authenticated', 'public.complete_answer(uuid,text,text,text,text,uuid[])', 'execute'), 'Guests cannot complete arbitrary Answers');
select ok(not has_function_privilege('authenticated', 'public.fail_answer(uuid)', 'execute'), 'Guests cannot mutate Answer failure state directly');

-- The transaction-only grants let pgTAP exercise the server wrappers while
-- retaining authenticated RLS visibility checks below. Production grants only
-- these wrappers to service_role.
grant execute on function public.begin_grounded_question(uuid, uuid, text, uuid) to authenticated;
grant execute on function public.retrieve_grounded_passages(uuid, uuid, extensions.vector, integer, double precision) to authenticated;
grant execute on function public.record_grounded_evidence(uuid, uuid, uuid[]) to authenticated;
grant execute on function public.complete_grounded_answer(uuid, uuid, text, text, text, text, uuid[]) to authenticated;
grant execute on function public.fail_grounded_answer(uuid, uuid) to authenticated;

